    if (date) text += `🕒 ${escapeHtml(date)}\n`;
    if (link) text += `🔗 <a href="${escapeHtml(link)}">Link</a>\n`;
    text += '\n';
  }
}

return [{ json: { chatId: source.chatId, text: text.trim() } }];
